<table class="crm-table"><tr><th>Name</th><th>Email</th><th>Phone</th><th>Portal</th><th>Status</th><th>Action</th></tr><?php foreach($clients as $c): ?><tr><td><?= esc($c['name']) ?></td><td><?= esc($c['email']) ?></td><td><?= esc($c['phone']) ?></td><td><?php if(!empty($c['portal_user_id'])): ?><span class="portal active">ACTIVE</span><?php else: ?><span class="portal">NONE</span><?php endif; ?></td><td><?= esc($c['status']) ?></td><td><a href="<?= site_url('admin/crm/clients/'.$c['id'].'/edit') ?>">Edit</a> · <a href="<?= site_url('admin/crm/clients/'.$c['id'].'/delete') ?>" onclick="return confirm('Delete this client and linked portal account?')">Delete</a></td></tr><?php endforeach; ?></table></div>
<style>.crm-wrap{max-width:1200px;margin:110px auto;padding:0 24px}.crm-btn{display:inline-block;padding:10px 14px;border:1px solid rgba(180,150,95,.35);border-radius:10px;color:inherit;text-decoration:none}.crm-btn.primary{background:#b89b5e;color:#111}.crm-table{width:100%;border-collapse:collapse}.crm-table th,.crm-table td{padding:12px;border-bottom:1px solid rgba(180,150,95,.18);text-align:left}.flash{padding:12px;border-radius:10px;margin:15px 0}.success{background:rgba(80,160,100,.12)}.error{background:rgba(200,70,70,.12)}.credentials{margin:18px 0;padding:20px;border:1px solid rgba(184,155,94,.45);border-radius:14px;background:rgba(184,155,94,.08)}.credentials>div:first-child{display:flex;justify-content:space-between;gap:12px;align-items:center}.mail-status{font-size:12px;padding:6px 9px;border-radius:999px}.mail-status.ok{background:rgba(70,160,100,.15)}.mail-status.warn{background:rgba(220,160,60,.18)}.cred-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:16px}.cred-grid div{padding:12px;border:1px solid rgba(180,150,95,.2);border-radius:10px}.cred-grid small,.cred-grid b{display:block}.cred-grid small{opacity:.65;margin-bottom:6px}.password{font-family:monospace;letter-spacing:.5px}.warning{font-size:12px;opacity:.7;margin-bottom:0}.portal{font-size:11px;padding:5px 8px;border-radius:999px;background:rgba(255,255,255,.08)}.portal.active{background:rgba(70,160,100,.15)}@media(max-width:800px){.cred-grid{grid-template-columns:1fr}.credentials>div:first-child{display:block}.mail-status{display:inline-block;margin-top:8px}}</style></body></html>
